package android.widget;
public class RatingBar extends AbsSeekBar { public interface OnRatingBarChangeListener { void onRatingChanged(RatingBar bar,float rating,boolean fromUser); } private int stars=5; private float rating,step=.5f; private OnRatingBarChangeListener listener; public RatingBar(android.content.Context c) { super(c); } public RatingBar(android.content.Context c,android.util.AttributeSet a) { super(c,a); } public RatingBar(android.content.Context c,android.util.AttributeSet a,int s) { super(c,a,s); } public RatingBar(android.content.Context c,android.util.AttributeSet a,int s,int r) { super(c,a,s,r); } public void setNumStars(int n) { stars=n; } public int getNumStars() { return stars; } public void setRating(float r) { rating=Math.max(0,Math.min(stars,r)); if(listener!=null) listener.onRatingChanged(this,rating,false); } public float getRating() { return rating; } public void setStepSize(float s) { step=s; } public float getStepSize() { return step; } public void setOnRatingBarChangeListener(OnRatingBarChangeListener l) { listener=l; } }
